package loader

import (
	"debug/elf"
	"encoding/binary"
	"fmt"
	"io"
	"os"
)

// Bounds define the initial static Linux ELF profile, not host resource limits.
const (
	ELFPageSize          uint64 = 4096
	ELFAddressLimit      uint64 = 1 << 48
	MaxELFFileBytes             = 16 << 20
	MaxELFImageBytes     uint64 = 256 << 20
	MaxELFProgramHeaders        = 128
)

// ELFError classifies an invalid image independently of its diagnostic message.
type ELFError struct{ Kind, Detail string }

func (e *ELFError) Error() string { return "ELF " + e.Kind + ": " + e.Detail }
func elfError(kind, format string, args ...any) error {
	return &ELFError{kind, fmt.Sprintf(format, args...)}
}

// ELFSegment owns page-rounded mapping bytes, including the file-backed page
// prefix and zero BSS. Data starts at Address rounded down to ELFPageSize.
// Overlapping mapping pages are unsupported.
type ELFSegment struct {
	Address, MemorySize uint64
	Flags               elf.ProgFlag
	Data                []byte
}

// ELFImage is a validated static AArch64 executable snapshot.
// Callers own this value and its bytes; edits are not revalidated automatically.
type ELFImage struct {
	Entry, ProgramHeaderAddress uint64
	ProgramHeaderCount          uint16
	Segments                    []ELFSegment
}

// LoadELF reads a bounded file and validates program headers. Sections are unused.
func LoadELF(path string) (*ELFImage, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	b, err := io.ReadAll(io.LimitReader(f, MaxELFFileBytes+1))
	if err != nil {
		return nil, err
	}
	return ParseELF(b)
}

// ParseELF accepts ELF64 LE AArch64 ET_EXEC with no dynamic runtime requirements.
// Validation completes before any segment bytes are copied into the result.
func ParseELF(b []byte) (*ELFImage, error) {
	if len(b) > MaxELFFileBytes {
		return nil, elfError("limit", "file exceeds %d bytes", MaxELFFileBytes)
	}
	if len(b) < 64 {
		return nil, elfError("malformed", "truncated header")
	}
	if string(b[:4]) != "\x7fELF" {
		return nil, elfError("malformed", "bad magic")
	}
	if b[4] != 2 || b[5] != 1 || b[6] != 1 {
		return nil, elfError("unsupported", "requires ELF64 little-endian version 1")
	}
	if (b[7] != 0 && b[7] != 3) || b[8] != 0 {
		return nil, elfError("unsupported", "OS ABI/version")
	}
	u := binary.LittleEndian
	if u.Uint16(b[16:]) != uint16(elf.ET_EXEC) || u.Uint16(b[18:]) != uint16(elf.EM_AARCH64) {
		return nil, elfError("unsupported", "requires AArch64 ET_EXEC (no PIE)")
	}
	if u.Uint32(b[20:]) != 1 || u.Uint16(b[52:]) != 64 || u.Uint16(b[54:]) != 56 {
		return nil, elfError("malformed", "header version or size")
	}
	if u.Uint32(b[48:]) != 0 {
		return nil, elfError("unsupported", "nonzero architecture flags")
	}
	entry, phoff := u.Uint64(b[24:]), u.Uint64(b[32:])
	count := u.Uint16(b[56:])
	if count == 0 || count > MaxELFProgramHeaders {
		return nil, elfError("limit", "program header count %d", count)
	}
	tableSize := uint64(count) * 56
	if phoff < 64 || phoff > uint64(len(b)) || tableSize > uint64(len(b))-phoff {
		return nil, elfError("malformed", "program header table outside file")
	}
	image := &ELFImage{Entry: entry, ProgramHeaderCount: count}
	var total, previousEnd uint64
	var phdr *elf.ProgHeader
	var stackSeen bool
	var headerAddresses []uint64
	for i := uint16(0); i < count; i++ {
		h := b[phoff+uint64(i)*56:]
		p := elf.ProgHeader{Type: elf.ProgType(u.Uint32(h)), Flags: elf.ProgFlag(u.Uint32(h[4:])), Off: u.Uint64(h[8:]), Vaddr: u.Uint64(h[16:]), Filesz: u.Uint64(h[32:]), Memsz: u.Uint64(h[40:]), Align: u.Uint64(h[48:])}
		if p.Type != elf.PT_NULL && (p.Off > uint64(len(b)) || p.Filesz > uint64(len(b))-p.Off) {
			return nil, elfError("malformed", "program header %d file bounds", i)
		}
		switch p.Type {
		case elf.PT_INTERP, elf.PT_DYNAMIC, elf.PT_TLS, elf.PT_GNU_RELRO:
			return nil, elfError("unsupported", "program header %d requires %s", i, p.Type)
		case elf.PT_GNU_STACK:
			if stackSeen {
				return nil, elfError("malformed", "duplicate GNU_STACK")
			}
			stackSeen = true
			if p.Flags != elf.PF_R|elf.PF_W {
				return nil, elfError("unsupported", "stack must be read/write and non-executable")
			}
			continue
		case elf.PT_PHDR:
			if phdr != nil || len(image.Segments) > 0 {
				return nil, elfError("malformed", "PHDR must be unique and precede load segments")
			}
			header := p
			phdr = &header
			continue
		case elf.PT_NULL, elf.PT_NOTE:
			continue
		case elf.PT_LOAD:
		default:
			return nil, elfError("unsupported", "program header %d type %#x", i, uint32(p.Type))
		}
		if p.Filesz > p.Memsz || p.Off > uint64(len(b)) || p.Filesz > uint64(len(b))-p.Off {
			return nil, elfError("malformed", "segment %d file bounds", i)
		}
		if p.Align > 1 && (p.Align&(p.Align-1) != 0 || p.Vaddr%p.Align != p.Off%p.Align) {
			return nil, elfError("malformed", "segment %d alignment", i)
		}
		if p.Vaddr%ELFPageSize != p.Off%ELFPageSize {
			return nil, elfError("malformed", "segment %d page offset mismatch", i)
		}
		if p.Flags & ^(elf.PF_R|elf.PF_W|elf.PF_X) != 0 {
			return nil, elfError("unsupported", "segment %d permission flags", i)
		}
		if p.Memsz == 0 {
			continue
		}
		if p.Vaddr < ELFPageSize || p.Vaddr >= ELFAddressLimit || p.Memsz > ELFAddressLimit-p.Vaddr {
			return nil, elfError("malformed", "segment %d address range", i)
		}
		start := p.Vaddr & ^(ELFPageSize - 1)
		end := (p.Vaddr + p.Memsz + ELFPageSize - 1) &^ (ELFPageSize - 1)
		if start < previousEnd {
			return nil, elfError("unsupported", "segment %d has overlapping or unordered mapping pages", i)
		}
		previousEnd = end
		if end-start > MaxELFImageBytes-total {
			return nil, elfError("limit", "mapped image exceeds %d bytes", MaxELFImageBytes)
		}
		total += end - start
		// Copy the file-backed mapping, not just bytes from p_vaddr. Linux
		// maps the first file page including its prefix. The final file page
		// remains file-backed unless a BSS tail requires zeroing it.
		fileStart := p.Off & ^(ELFPageSize - 1)
		fileEnd := min(uint64(len(b)), fileStart+end-start)
		if p.Memsz > p.Filesz {
			fileEnd = p.Off + p.Filesz
		}
		if p.Filesz == 0 {
			fileEnd = fileStart
		} // Pure BSS maps anonymous zero pages, including the prefix.
		image.Segments = append(image.Segments, ELFSegment{Address: p.Vaddr, MemorySize: p.Memsz, Flags: p.Flags, Data: b[fileStart:fileEnd]})
		if phoff >= p.Off && phoff-p.Off <= p.Filesz && tableSize <= p.Filesz-(phoff-p.Off) && p.Flags&elf.PF_R != 0 {
			headerAddresses = append(headerAddresses, p.Vaddr+(phoff-p.Off))
		}
	}
	if len(image.Segments) == 0 {
		return nil, elfError("malformed", "no nonempty load segments")
	}
	if len(headerAddresses) == 0 {
		return nil, elfError("unsupported", "program header table must be file-backed in a readable load segment")
	}
	image.ProgramHeaderAddress = headerAddresses[0]
	if phdr != nil {
		found := false
		for _, addr := range headerAddresses {
			if addr == phdr.Vaddr {
				found = true
			}
		}
		if !found || phdr.Off != phoff || phdr.Filesz != tableSize || phdr.Memsz != tableSize {
			return nil, elfError("malformed", "PHDR does not describe mapped program header table")
		}
		image.ProgramHeaderAddress = phdr.Vaddr
	}
	executable := false
	for _, s := range image.Segments {
		if entry >= s.Address && entry-s.Address <= s.MemorySize && 4 <= s.MemorySize-(entry-s.Address) && s.Flags&elf.PF_X != 0 {
			executable = true
		}
	}
	if entry%4 != 0 || !executable {
		return nil, elfError("malformed", "entry must address a complete aligned executable instruction")
	}
	for i := range image.Segments {
		s := &image.Segments[i]
		start := s.Address & ^(ELFPageSize - 1)
		end := (s.Address + s.MemorySize + ELFPageSize - 1) &^ (ELFPageSize - 1)
		data := make([]byte, end-start)
		copy(data, s.Data)
		s.Data = data
	}
	return image, nil
}

base_capability.runtime_source:
package linuxuser

import (
	"context"
	"debug/elf"
	"errors"
	"fmt"
	"time"

	"github.com/sarchlab/poros/pkg/emu"
	"golang.org/x/arch/arm64/arm64asm"
)

const MaxOutputBytes = 64 << 20

// RunOptions bounds host work separately from the deterministic instruction
// budget. Zero values select 1M instructions, 2 seconds and 1 MiB total output.
type RunOptions struct {
	MaxInstructions uint64
	Timeout         time.Duration
	MaxOutput       int
}

// Result captures bytes without text conversion (JSON encodes []byte as base64).
// ExitStatus is present only for a guest exit syscall. Instructions counts
// completed guest instructions, including successful/errno-returning syscalls.
// Faulting and unsupported instructions/syscalls are not counted.
type Result struct {
	Termination  string `json:"termination"`
	ExitStatus   *int   `json:"exit_status"`
	Instructions uint64 `json:"instructions"`
	PC           uint64 `json:"pc"`
	Stdout       []byte `json:"stdout_base64"`
	Stderr       []byte `json:"stderr_base64"`
	Diagnostic   string `json:"diagnostic,omitempty"`
}

// Execution owns one run and is a live resource for either functional or timing
// driving. Close releases its deadline; it never shares mutable state across runs.
type Execution struct {
	process *Process
	options RunOptions
	ctx     context.Context
	cancel  context.CancelFunc
	result  Result
	done    bool
	memory  trackedMemory
}

// NewExecution claims this process exactly once; all execution modes share it.
func (p *Process) NewExecution(ctx context.Context, o RunOptions) (*Execution, error) {
	r := Result{Stdout: []byte{}, Stderr: []byte{}}
	if p.ran {
		return nil, fmt.Errorf("process has already run")
	}
	if o.MaxInstructions == 0 {
		o.MaxInstructions = 1_000_000
	}
	if o.Timeout == 0 {
		o.Timeout = 2 * time.Second
	}
	if o.MaxOutput == 0 {
		o.MaxOutput = 1 << 20
	}
	if o.Timeout < 0 || o.MaxOutput < 0 || o.MaxOutput > MaxOutputBytes {
		return nil, fmt.Errorf("invalid execution limits")
	}
	p.ran = true
	ctx, cancel := context.WithTimeout(ctx, o.Timeout)

	x := &Execution{process: p, options: o, ctx: ctx, cancel: cancel, result: r}
	x.memory.space = p.Memory
	return x, nil
}
func (x *Execution) Close()                          { x.cancel() }
func (x *Execution) Result() Result                  { return x.result }
func (x *Execution) CPURegisters() *emu.Registers    { return &x.process.Registers }
func (x *Execution) Stopped() bool                   { return x.done }
func (x *Execution) MemoryAccesses() []emu.MemAccess { return x.memory.accesses }
func (x *Execution) Peek(pc uint64) (arm64asm.Inst, error) {
	var b [4]byte
	if err := x.process.Memory.Fetch(pc, b[:]); err != nil {
		return arm64asm.Inst{}, err
	}
	return arm64asm.Decode(b[:])
}
func (x *Execution) StepDetailed() (arm64asm.Inst, bool, error) {
	pc := x.process.Registers.PC
	inst, _ := x.Peek(pc)
	before := x.result.Instructions
	x.memory.accesses = x.memory.accesses[:0]
	_, err := x.step()
	if err != nil {
		return inst, false, err
	}
	if x.result.Instructions == before {
		x.memory.accesses = x.memory.accesses[:0]
		return inst, false, fmt.Errorf("%s: %s", x.result.Termination, x.result.Diagnostic)
	}
	return inst, x.process.Registers.PC != pc+4, nil
}
func (x *Execution) step() (Result, error) {
	p, o := x.process, x.options
	r := &x.result
	ctx := x.ctx
	finish := func(reason, detail string) (Result, error) {
		x.done = true
		r.Termination = reason
		r.Diagnostic = detail
		r.PC = p.Registers.PC
		return *r, nil
	}
	if x.done {
		return *r, fmt.Errorf("execution already stopped")
	}
	if r.Instructions >= o.MaxInstructions {
		return finish("instruction_limit", fmt.Sprintf("completed %d instructions", o.MaxInstructions))
	}
	select {
	case <-ctx.Done():
		return finish("time_limit", ctx.Err().Error())
	default:
	}
	step, err := emu.StepChecked(&p.Registers, &x.memory)
	if err != nil {
		var fault *emu.StepError
		if errors.As(err, &fault) {
			return finish(fault.Kind, err.Error())
		}
		return finish("execution_fault", err.Error())
	}
	if step.Syscall {
		number := p.Registers.GPR[8]
		switch number {
		case 93, 94:
			code := int(p.Registers.GPR[0] & 255)
			r.ExitStatus = &code
			r.Instructions++
			p.Registers.PC += 4
			return finish("exit", "")
		case 64:
			fd := uint32(p.Registers.GPR[0])
			addr := p.Registers.GPR[1]
			count := min(p.Registers.GPR[2], uint64(0x7ffff000))
			if fd != 1 && fd != 2 {
				p.Registers.GPR[0] = errno(9)
			} else if err := p.Memory.check(addr, int(count), elf.PF_R, "read"); err != nil {
				p.Registers.GPR[0] = errno(14)
			} else {
				if count > uint64(o.MaxOutput-len(r.Stdout)-len(r.Stderr)) {
					return finish("output_limit", fmt.Sprintf("write would exceed %d output bytes", o.MaxOutput))
				}
				b := make([]byte, int(count))
				if err := p.Memory.Read(addr, b); err != nil {
					return finish("execution_fault", err.Error())
				}
				if fd == 1 {
					r.Stdout = append(r.Stdout, b...)
				} else {
					r.Stderr = append(r.Stderr, b...)
				}
				p.Registers.GPR[0] = count
			}
			p.Registers.PC += 4
		default:
			return finish("unsupported_syscall", fmt.Sprintf("syscall %d at PC=%#x is unsupported", number, p.Registers.PC))
		}
	}
	r.Instructions++
	return *r, nil
}

func (p *Process) Run(ctx context.Context, o RunOptions) (Result, error) {
	x, err := p.NewExecution(ctx, o)
	if err != nil {
		return Result{}, err
	}
	defer x.Close()
	for !x.Stopped() {
		if _, _, err := x.StepDetailed(); err != nil && !x.Stopped() {
			return x.Result(), fmt.Errorf("execution error without termination: %w", err)
		}
	}
	return x.Result(), nil
}

type trackedMemory struct {
	space    *AddressSpace
	accesses []emu.MemAccess
}

func (m *trackedMemory) Fetch(a uint64, b []byte) error { return m.space.Fetch(a, b) }
func (m *trackedMemory) Read(a uint64, b []byte) error {
	if err := m.space.Read(a, b); err != nil {
		return err
	}
	m.record(a, len(b), false)
	return nil
}
func (m *trackedMemory) Write(a uint64, b []byte) error {
	if err := m.space.Write(a, b); err != nil {
		return err
	}
	m.record(a, len(b), true)
	return nil
}
func (m *trackedMemory) record(a uint64, n int, w bool) {
	for n > 0 {
		// Split at natural word boundaries so an unaligned operation crossing
		// a cache line is represented on both sides.
		width := min(n, 8-int(a%8))
		m.accesses = append(m.accesses, emu.MemAccess{Addr: a, Size: width, IsWrite: w})
		a += uint64(width)
		n -= width
	}
}
func errno(n uint64) uint64 { return ^n + 1 }
